        external
        view
        returns (
            uint256 amount,
            uint256 creationTime,
            uint256 freezePeriod,
            uint256 profitPercent,
            uint256 stakeAmount,
            uint256 stakeTime,
            uint256 collectedTime,
            uint256 collectedReward,
            uint256 stakingRewardLimit,
            bool isClosed
        );

    function userBalance(
        address userAddress
    ) external view returns (uint256 balance);
}

interface IKokonut {
    function flashLoan(address borrower, uint256[] memory amounts, bytes memory data) external;
}

interface ISynapseETHPools {
    function flashLoan(address receiver, address token, uint256 amount, bytes memory params) external;
